export interface ConnectorConfig {
  airtableBaseId: string
  airtableTableName: string
  airtablePat?: string
  fetch?: typeof fetch
}

export interface ShopifyOrderPaidPayload {
  id: number | string
  email?: string
  total_price: string
  order_number?: number
  customer?: {
    email?: string
  }
}

export interface AirtableCreateRecordResponse {
  id: string
  fields: {
    'Order ID': string
    'Customer Email': string
    Total: number
  }
  createdTime: string
}

export interface HandleResult {
  airtableRecordId: string
  orderId: string
}

function getFetch(config: ConnectorConfig): typeof fetch {
  return config.fetch ?? fetch
}

function getPat(config: ConnectorConfig): string {
  return config.airtablePat ?? process.env.AIRTABLE_PAT ?? ''
}

function validatePayload(payload: ShopifyOrderPaidPayload): void {
  if (payload.id === undefined || payload.id === null) {
    throw new Error('Missing required field: id')
  }
  if (!payload.customer?.email && !payload.email) {
    throw new Error('Missing required field: customer.email (or email)')
  }
  if (payload.total_price === undefined || payload.total_price === null) {
    throw new Error('Missing required field: total_price')
  }
}

function buildAirtableUrl(config: ConnectorConfig): string {
  return `https://api.airtable.com/v0/${config.airtableBaseId}/${config.airtableTableName}`
}

function mapFields(payload: ShopifyOrderPaidPayload): Record<string, unknown> {
  const orderId = String(payload.id)
  const customerEmail = payload.customer?.email ?? payload.email ?? ''
  const total = Number(payload.total_price)

  return {
    'Order ID': orderId,
    'Customer Email': customerEmail,
    Total: total,
  }
}

export async function handle(
  payload: ShopifyOrderPaidPayload,
  config: ConnectorConfig,
): Promise<HandleResult> {
  validatePayload(payload)

  const pat = getPat(config)
  if (!pat) {
    throw new Error('Airtable Personal Access Token not configured (airtablePat or AIRTABLE_PAT)')
  }

  const url = buildAirtableUrl(config)
  const fields = mapFields(payload)
  const body = JSON.stringify({ fields })

  const fetchFn = getFetch(config)
  const response = await fetchFn(url, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${pat}`,
      'Content-Type': 'application/json',
    },
    body,
  })

  if (!response.ok) {
    throw new Error(`Airtable create record failed: ${response.status} ${response.statusText} at ${url}`)
  }

  const data = (await response.json()) as AirtableCreateRecordResponse
  return {
    airtableRecordId: data.id,
    orderId: String(payload.id),
  }
}

